python3 << 'EOF'
import fitz, numpy as np
d = fitz.open('eprint/img/Quax_LNF_2024_150.pdf')
p = d[0]
draws = p.get_drawings()

def to_pts(dr):
    pts=[]
    for it in dr['items']:
        if it[0]=='l':
            pts.append((it[1].x,it[1].y)); pts.append((it[2].x,it[2].y))
        elif it[0]=='c':
            for pt in it[1:]:
                pts.append((pt.x,pt.y))
    # dedupe consecutive
    out=[]
    for pt in pts:
        if not out or (abs(pt[0]-out[-1][0])>1e-9 or abs(pt[1]-out[-1][1])>1e-9):
            out.append(pt)
    return out

for i,dr in enumerate(draws):
    col=str(dr.get('color')); fill=str(dr.get('fill'))
    if '0.1215' in fill or '0.5411' in col:
        pts=to_pts(dr)
        print(i, dr['type'], col, fill, 'npts', len(pts))
        xs=[pt[0] for pt in pts]; ys=[pt[1] for pt in pts]
        print('  xrange', min(xs), max(xs), 'yrange', min(ys), max(ys))
EOF
